-- STAGE-14C1 Task 1 —— 杠杆/MM 双重分级表 t_symbol_leverage_tier + 全 symbol tier seed。
-- schema 由 Flyway 连接绑定（falconx_trading），严禁写 USE（STAGE-14B root bug 教训）。
-- seed 为 owner（market）t_symbol(status=1) 的 build-time 静态快照，由
--   tools/tier-seed/generate_tier_seed.py 按 master 设计 §5.2 CASE 映射 §5.1 模板生成；
--   trading-core 运行时不跨 schema 直读 falconx_market。
-- category 1-5 严格按 §5.2 CASE；category 6(stock)/7(etf) 经控制者确认复用 T10（股指+能源）模板。
-- 注：master §5.1 T9 tier3 原写 50x×2.5%=1.25 违反 CHECK，已修正为 50x/2.0%（与 T6/T7 同档一致，50×0.02=1.0）。

CREATE TABLE t_symbol_leverage_tier (
    id              BIGINT       PRIMARY KEY COMMENT '主键ID',
    symbol          VARCHAR(32)  NOT NULL,
    group_code      VARCHAR(32)  NOT NULL DEFAULT 'default',
    tier_no         TINYINT      NOT NULL,
    notional_lower  DECIMAL(24,8) NOT NULL,
    notional_upper  DECIMAL(24,8) NULL COMMENT 'NULL=无上限（最高档）',
    max_leverage    INT          NOT NULL,
    mm_rate         DECIMAL(8,6) NOT NULL,
    enabled         TINYINT      NOT NULL DEFAULT 1,
    created_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at      DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uk_symbol_group_tier (symbol, group_code, tier_no),
    INDEX idx_symbol_group_lower (symbol, group_code, notional_lower),
    CONSTRAINT chk_tier_leverage_mm CHECK (max_leverage * mm_rate <= 1.0)
) ENGINE=InnoDB COMMENT='杠杆/MM 双重分级表';

